function escapeXML(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

var cardWidth = 200;
var cardHeight = 220;
var gap = 10;
var startX = 10;
var startY = 10;

var inner = evidence.map(function(record, index) {
  var x = startX + index * (cardWidth + gap);
  var y = startY;

  var label = escapeXML(record.label != null ? record.label : 'Not supplied');
  var variable = escapeXML(record.variable != null ? record.variable : 'Not supplied');
  var val = escapeXML(record.value != null ? String(record.value) : 'Not supplied');
  var unit = escapeXML(record.unit != null ? record.unit : 'Unit not supplied');
  var recId = escapeXML(record.id);

  return '<g data-record-id="' + recId + '" transform="translate(' + x + ',' + y + ')">' +
    '<rect x="0" y="0" width="' + cardWidth + '" height="' + cardHeight + '" fill="#f8f9fa" stroke="#cccccc" stroke-width="1" rx="6" ry="6"/>' +
    '<rect x="0" y="0" width="' + cardWidth + '" height="36" fill="#e9ecef" rx="6" ry="6"/>' +
    '<text x="10" y="24" font-family="sans-serif" font-size="14" font-weight="bold" fill="#212529">' + label + '</text>' +
    '<text x="10" y="58" font-family="sans-serif" font-size="11" fill="#6c757d">' + variable + '</text>' +
    '<text x="10" y="80" font-family="sans-serif" font-size="10" fill="#212529">' + val + '</text>' +
    '<text x="10" y="120" font-family="sans-serif" font-size="11" fill="#6c757d">' + unit + '</text>' +
    '</g>';
}).join('');

return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 240">' + inner + '</svg>';
